"""One-shot script: merges the new landing-page translation strings into the
six existing locale JSON files. Re-runnable — existing keys are preserved
(only adds, never overwrites), so a translator can hand-polish any specific
entry later and a subsequent run of this script won't clobber it.

Run: `python scripts/merge_translations.py`
"""
from __future__ import annotations

import json
from pathlib import Path

# Each locale gets the same set of keys; values are the translations.
# HTML inside the keys is reproduced verbatim in the values (the class names
# never change and `<code>` etc. must round-trip). HTML entities (`&amp;`)
# stay as &amp; — i18n.js feeds the result back into innerHTML.
